//! Deterministic, omission-aware resource discovery for Worldgen P05 F01-F04.
use std::collections::{BTreeMap,BTreeSet};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.resource-discovery-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ResourceCandidate{pub resource_id:String,pub resource_type:String,pub capabilities:Vec<String>,pub fitness_milli:u16,pub availability:String,pub evidence_digest:ContentHash,pub provenance_digest:ContentHash,pub artifact_digest:ContentHash,pub replay_identity:ContentHash,pub permitted:bool,pub raw_data_local:bool,pub negative_result:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ResourceDiscoveryRequest{pub need_id:String,pub consumer:String,pub intent:String,pub required_capability_order:Vec<String>,pub candidate_order:Vec<String>,pub candidates:Vec<ResourceCandidate>,pub max_results:usize,pub minimum_fitness_milli:u16,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub federation_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct QualifiedResource{pub resource_id:String,pub resource_type:String,pub fitness_milli:u16,pub rank:u32,pub capability_order:Vec<String>,pub artifact_digest:ContentHash}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ResourceDiscoveryReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub need_id:String,pub consumer:String,pub disposition:String,pub required_capability_order:Vec<String>,pub candidate_order:Vec<String>,pub qualified_order:Vec<String>,pub stale_order:Vec<String>,pub protected_order:Vec<String>,pub unavailable_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub resources:Vec<QualifiedResource>,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub replay_identity:ContentHash,pub discovery_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ResourceDiscoveryError{#[error("invalid resource discovery request: {0}")]Invalid(String),#[error("resource discovery artifact failed: {0}")]Artifact(String),#[error("invalid resource discovery receipt: {0}")]Receipt(String)}
fn valid_hash(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn sorted(v:&[String])->Vec<String>{let mut o=v.to_vec();o.sort();o.dedup();o}fn digest_vec(v:&serde_json::Value)->Result<ContentHash,ResourceDiscoveryError>{ContentHash::of_value(v).map_err(|e|ResourceDiscoveryError::Artifact(e.to_string()))}
impl ResourceDiscoveryReceipt{pub fn validate(&self)->Result<(),ResourceDiscoveryError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.need_id.trim().is_empty()||self.consumer.trim().is_empty()||self.required_capability_order.is_empty()||self.candidate_order.is_empty()||self.effect_receipts.is_empty()||![&self.replay_identity,&self.discovery_digest].into_iter().all(valid_hash){return Err(ResourceDiscoveryError::Receipt("resource identity, candidates, locality, digests, or effects are incomplete".into()));}for v in [&self.required_capability_order,&self.candidate_order,&self.qualified_order,&self.stale_order,&self.protected_order,&self.unavailable_order,&self.unknown_order,&self.omitted_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !ordered(v){return Err(ResourceDiscoveryError::Receipt("resource vectors are not canonical".into()));}}let c=self.candidate_order.iter().cloned().collect::<BTreeSet<_>>();let p=self.qualified_order.iter().chain(&self.stale_order).chain(&self.protected_order).chain(&self.unavailable_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if c.len()!=self.candidate_order.len()||p.len()!=c.len()||p.iter().cloned().collect::<BTreeSet<_>>()!=c{return Err(ResourceDiscoveryError::Receipt("resource candidate states do not partition".into()));}if self.resources.len()!=self.qualified_order.len()||self.resources.iter().map(|r|r.resource_id.clone()).collect::<BTreeSet<_>>()!=self.qualified_order.iter().cloned().collect(){return Err(ResourceDiscoveryError::Receipt("qualified resources do not match partition".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.discovery_digest.as_str()){return Err(ResourceDiscoveryError::Receipt("resource artifact digest is inconsistent".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("discover:worldgen-resource:")){return Err(ResourceDiscoveryError::Receipt("resource effect is outside discovery gate".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["preclinical neuroscientist","bioinformatician","imaging core scientist","benchmark curator"],"behavior":format!("discover fitness-qualified research resources for {scale}"),"value":"turns typed resource needs into ranked, auditable, locally governed resource choices without leaking protected data","input_schema":input_schema,"output_schema":"QualifiedResourceSet1@1","effects":["discover:worldgen-resource","block:unsafe-release"],"permissions":["discover:local-research-resource"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn discover(request:&ResourceDiscoveryRequest,feature_id:&str,version:&str,scale:&str,require_federation:bool)->Result<ResourceDiscoveryReceipt,ResourceDiscoveryError>{if request.need_id.trim().is_empty()||request.consumer.trim().is_empty()||request.intent.trim().is_empty()||request.required_capability_order.is_empty()||request.candidate_order.is_empty()||request.max_results==0||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!valid_hash(&request.replay_identity)||!ordered(&request.required_capability_order)||!ordered(&request.candidate_order)||request.candidate_order.iter().collect::<BTreeSet<_>>().len()!=request.candidate_order.len(){return Err(ResourceDiscoveryError::Invalid("resource need, candidates, locality, boundary, ordering, or replay is invalid".into()));}if require_federation&&!request.federation_approved{return Err(ResourceDiscoveryError::Invalid("resource federation approval is required".into()));}
let ids=request.candidate_order.iter().cloned().collect::<BTreeSet<_>>();let mut by_id=BTreeMap::new();for c in &request.candidates{if !ids.contains(&c.resource_id)||c.boundary!=PRECLINICAL_BOUNDARY||!c.raw_data_local||c.replay_identity!=request.replay_identity||![&c.evidence_digest,&c.provenance_digest,&c.artifact_digest,&c.replay_identity].into_iter().all(valid_hash){return Err(ResourceDiscoveryError::Invalid("resource candidate identity, provenance, replay, locality, or boundary is invalid".into()));}if by_id.insert(c.resource_id.clone(),c).is_some(){return Err(ResourceDiscoveryError::Invalid("duplicate resource candidate".into()));}}
let required=request.required_capability_order.iter().cloned().collect::<BTreeSet<_>>();let mut qualified=Vec::new();let mut stale=BTreeSet::new();let mut protected=BTreeSet::new();let mut unavailable=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();
for id in &ids{match by_id.get(id){None=>{omitted.insert(id.clone());omissions.insert(format!("resource:{}:missing",id));},Some(c) if c.negative_result=>{unknown.insert(id.clone());negative.insert(format!("resource:{}:negative-result-retained",id));},Some(c) if !request.policy_allow||!request.protected_closure||!c.permitted=>{protected.insert(id.clone());omissions.insert(format!("resource:{}:policy-or-permission-blocked",id));},Some(c) if c.availability=="stale"=>{stale.insert(id.clone());uncertainty.insert(format!("resource:{}:stale",id));},Some(c) if c.availability!="available"=>{unavailable.insert(id.clone());omissions.insert(format!("resource:{}:unavailable",id));},Some(c) if c.fitness_milli<request.minimum_fitness_milli||!required.iter().all(|cap|c.capabilities.contains(cap))=>{unknown.insert(id.clone());uncertainty.insert(format!("resource:{}:fitness-or-capability-below-threshold",id));},Some(c)=>qualified.push(c)}}
qualified.sort_by(|a,b|b.fitness_milli.cmp(&a.fitness_milli).then(a.resource_id.cmp(&b.resource_id)));let selected=qualified.iter().take(request.max_results).enumerate().map(|(i,c)|QualifiedResource{resource_id:c.resource_id.clone(),resource_type:c.resource_type.clone(),fitness_milli:c.fitness_milli,rank:(i+1)as u32,capability_order:required.iter().cloned().collect(),artifact_digest:c.artifact_digest.clone()}).collect::<Vec<_>>();for c in qualified.iter().skip(request.max_results){omitted.insert(c.resource_id.clone());omissions.insert(format!("resource:{}:max-results",c.resource_id));}
if require_federation&&!request.federation_approved{omissions.insert("request:federation-approval-missing".into());}let authority=request.policy_allow&&request.protected_closure&&(!require_federation||request.federation_approved);let disposition=if !authority{"blocked"}else if selected.is_empty(){"unknown"}else if selected.len()==request.candidate_order.len()&&omissions.is_empty()&&uncertainty.is_empty()&&negative.is_empty(){"qualified"}else{"partial"};let qualified_ids=selected.iter().map(|r|r.resource_id.clone()).collect::<BTreeSet<_>>();let mut omitted_all=omitted;for id in ids.difference(&qualified_ids).filter(|id|!stale.contains(*id)&&!protected.contains(*id)&&!unavailable.contains(*id)&&!unknown.contains(*id)){omitted_all.insert((*id).clone());}
let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("discover:worldgen-resource:{}",request.need_id)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"need_id":request.need_id,"consumer":request.consumer,"scale":scale,"disposition":disposition,"required_capability_order":required,"candidate_order":ids,"qualified_order":qualified_ids,"stale_order":stale,"protected_order":protected,"unavailable_order":unavailable,"unknown_order":unknown,"omitted_order":omitted_all,"resources":selected,"omissions":omissions,"uncertainty":uncertainty,"negative_evidence":negative,"replay_identity":request.replay_identity,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY,"raw_candidates":false});let discovery_digest=digest_vec(&payload)?;let receipt=ResourceDiscoveryReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),need_id:request.need_id.clone(),consumer:request.consumer.clone(),disposition:disposition.into(),required_capability_order:required.iter().cloned().collect(),candidate_order:ids.iter().cloned().collect(),qualified_order:qualified_ids.iter().cloned().collect(),stale_order:stale.iter().cloned().collect(),protected_order:protected.iter().cloned().collect(),unavailable_order:unavailable.iter().cloned().collect(),unknown_order:unknown.iter().cloned().collect(),omitted_order:omitted_all.iter().cloned().collect(),resources:selected,omissions:omissions.into_iter().collect(),uncertainty:uncertainty.into_iter().collect(),negative_evidence:negative.into_iter().collect(),replay_identity:request.replay_identity.clone(),discovery_digest:discovery_digest.clone(),effect_receipts:effects,artifact:json!({"artifact_id":format!("worldgen-resource-set:{}",request.need_id),"content_type":CONTENT_TYPE,"content_hash":discovery_digest,"raw_candidates":false,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn req()->ResourceDiscoveryRequest{let r=h("replay");let c=ResourceCandidate{resource_id:"dataset:a".into(),resource_type:"dataset".into(),capabilities:vec!["imaging".into()],fitness_milli:900,availability:"available".into(),evidence_digest:h("e"),provenance_digest:h("p"),artifact_digest:h("a"),replay_identity:r.clone(),permitted:true,raw_data_local:true,negative_result:false,boundary:PRECLINICAL_BOUNDARY.into()};ResourceDiscoveryRequest{need_id:"need:a".into(),consumer:"scientist".into(),intent:"find imaging".into(),required_capability_order:vec!["imaging".into()],candidate_order:vec!["dataset:a".into()],candidates:vec![c],max_results:8,minimum_fitness_milli:500,replay_identity:r,policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified_resource_is_ranked(){let r=discover(&req(),"AFA-worldgen-P05-F01","worldgen-local-resource-discovery/1.0","local single-study",false).unwrap();assert_eq!(r.disposition,"qualified");assert_eq!(r.resources[0].rank,1);}#[test]fn stale_resource_is_explicit(){let mut q=req();q.candidates[0].availability="stale".into();let r=discover(&q,"AFA-worldgen-P05-F02","worldgen-multimodal-resource-discovery/1.0","multimodal multi-study",false).unwrap();assert_eq!(r.disposition,"unknown");assert!(r.stale_order.contains(&"dataset:a".into()));}}

